const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var paris = ee.Geometry.Point(2.3522, 48.8566).buffer(1000); // 1km buffer
  var targetDate = '2024-08-06';
  var targetTimeUTC = '11:40'; // 1:40 pm Paris time = 11:40 UTC (UTC+2)

  // Create time window: 30 minutes before and after target
  var startTime = ee.Date(targetDate + 'T' + '11:10:00');
  var endTime = ee.Date(targetDate + 'T' + '12:10:00');

  // 2. Data Acquisition - Try MODIS Aqua first
  var aquaCollection = ee.ImageCollection('MODIS/061/MYD11_L2')
    .filterBounds(paris)
    .filterDate(startTime, endTime);

  var collectionSize = aquaCollection.size().getInfo();
  print('Aqua images in window:', collectionSize);

  // If no Aqua images, try MODIS Terra
  var img;
  var source = 'Aqua';
  if (collectionSize === 0) {
    print('No Aqua images, trying Terra...');
    var terraCollection = ee.ImageCollection('MODIS/061/MOD11_L2')
      .filterBounds(paris)
      .filterDate(startTime, endTime);
    collectionSize = terraCollection.size().getInfo();
    print('Terra images in window:', collectionSize);

    if (collectionSize === 0) {
      // Try wider window for both
      var widerStart = ee.Date(targetDate + 'T' + '10:00:00');
      var widerEnd = ee.Date(targetDate + 'T' + '13:00:00');
      aquaCollection = ee.ImageCollection('MODIS/061/MYD11_L2')
        .filterBounds(paris)
        .filterDate(widerStart, widerEnd);
      collectionSize = aquaCollection.size().getInfo();
      print('Aqua images in wider window:', collectionSize);

      if (collectionSize === 0) {
        print('No MODIS LST images found.');
        print('<answer>C1</answer>');
        return;
      }
      source = 'Aqua (wider)';
    } else {
      source = 'Terra';
      aquaCollection = terraCollection;
    }
  }

  // Get the first image
  img = ee.Image(aquaCollection.first());

  // 3. Processing - Mask clouds using QC band
  var qc = img.select('QC_Day');
  var mask = qc.bitwiseAnd(3).lt(2); // Bits 0-1: 00 or 01 = good or other quality
  var lstKelvin = img.select('LST_Day_1km').updateMask(mask);

  // Convert to Celsius: scale 0.02, offset -273.15
  var lstCelsius = lstKelvin.multiply(0.02).subtract(273.15);

  // 4. Calculate statistics
  var stats = lstCelsius.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: paris,
    scale: 1000,
    maxPixels: 1e9
  });

  var maxTemp = stats.get('LST_Day_1km').getInfo();
  var pixelCount = stats.get('LST_Day_1km_count').getInfo();

  print('Source:', source);
  print('Valid pixels:', pixelCount);

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    print('No valid LST pixels after cloud masking.');
    print('<answer>C2</answer>');
    return;
  }

  if (maxTemp === null || maxTemp === undefined || maxTemp > 100 || maxTemp < -100) {
    print('Invalid temperature value:', maxTemp);
    print('<answer>C3</answer>');
    return;
  }

  print('Max LST (°C):', maxTemp.toFixed(2));

  if (maxTemp > 32) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
